package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Declared direct-item bait slot fixtures, NOT a current native Trap GUI claim. */
public final class PestBaitTransferTest {
 static final long S=1_000_000_000L;static final ItemSnapshot AIR=new ItemSnapshot("","minecraft:air","","","",0,List.of(),true);
 static ItemSnapshot item(String id,int count){return new ItemSnapshot(id,"minecraft:paper","",id,"raw:"+id,count,List.of(),false);}static ItemSnapshot count(ItemSnapshot i,int n){return n==0?AIR:new ItemSnapshot(i.skyblockId(),i.minecraftId(),i.uuid(),i.name(),i.fingerprint(),n,i.lore(),i.protectedItem());}
 static void check(boolean v,String message){if(!v)throw new AssertionError(message);}
 static Map<Integer,ItemSnapshot> inventory(){var inv=new HashMap<Integer,ItemSnapshot>();for(int i=0;i<43;i++)inv.put(i,AIR);inv.put(10,item("PLANT_MATTER",8));return inv;}
 static final PestBaitTransfer.Layout LAYOUT=new PestBaitTransfer.Layout("Pest Trap #1",27,13,2);
 static MenuSnapshot menu(Map<Integer,ItemSnapshot> inv,ItemSnapshot bait){var slots=new ArrayList<MenuSnapshot.Slot>();for(int i=0;i<27;i++)slots.add(new MenuSnapshot.Slot(i,i==13?bait:AIR,false));for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(27+i,inv.get(i<27?i+9:i-27),true));return new MenuSnapshot(1,7,2,"Pest Trap #1",27,slots);}
 static PestTrapObservation traps(boolean empty){return new PestTrapObservation(Set.of(),true,empty?Set.of(1):Set.of(),true);}
 static final class F {
  Map<Integer,ItemSnapshot> inv=inventory();ItemSnapshot cursor=AIR,bait=AIR;InventoryReceipts items=new InventoryReceipts();CursorReceipts cursors=new CursorReceipts();AtomicBoolean owned=new AtomicBoolean(true);long now;int actions;PestBaitTransfer proof=new PestBaitTransfer(items,cursors,owned::get);PestBaitTransfer.Plan plan;
  F(int units){plan=PestBaitTransfer.select(new PestBaitTransfer.Rules("PLANT_MATTER",units,8,Set.of()),1,new PestBaitTransfer.Layout("Pest Trap #1",27,13,units),menu(inv,bait),inv,traps(true)).orElseThrow();check(proof.begin(plan,menu(inv,bait),inv,cursor,0),"explicit complete unchanged plan");}
  void arm(){check(proof.armNext(menu(inv,bait),inv,cursor,now),"phase-specific arm: "+proof.state()+"/"+proof.step()+" cursor="+cursor.count()+" source="+inv.get(10).count()+" bait="+bait.count());check(proof.ticket()!=null&&proof.ticket().click()==MenuContract.Click.PICKUP,"only exact PICKUP, never shift/throw");actions++;check(proof.sent(GuardedMenuAction.Result.SENT,now),"one bounded issued step");}
  void poll(boolean empty){now+=S/10;proof.poll(1,menu(inv,bait),inv,cursor,new PestBaitTransfer.TrapFrame(1,now,traps(empty)),false,now);}
  void pickup(boolean server){cursor=plan.item();inv.put(10,AIR);if(server){items.observe(1,7,28,AIR);cursors.observe(1,7,cursor,now+1);}poll(true);}
  void deposit(boolean server){bait=count(plan.item(),plan.units());cursor=count(plan.item(),plan.item().count()-plan.units());if(server){items.observe(1,7,13,bait);cursors.observe(1,7,cursor,now+1);}poll(false);}
  void returned(boolean server){inv.put(10,cursor);cursor=AIR;if(server){items.observe(1,7,28,inv.get(10));cursors.observe(1,7,AIR,now+1);}poll(false);}
 }
 public static void main(String[]args){
  var inv=inventory();check(PestBaitTransfer.select(PestBaitTransfer.Rules.defaults(),1,LAYOUT,menu(inv,AIR),inv,traps(true)).isEmpty(),"defaults grant no bait consumption");
  var rules=new PestBaitTransfer.Rules("PLANT_MATTER",2,8,Set.of());var partial=new HashMap<>(inv);partial.remove(42);check(PestBaitTransfer.select(rules,1,LAYOUT,menu(inv,AIR),partial,traps(true)).isEmpty(),"all43 including equipment required");
  var protectedInv=new HashMap<>(inv);var source=inv.get(10);protectedInv.put(10,new ItemSnapshot(source.skyblockId(),source.minecraftId(),"",source.name(),source.fingerprint(),8,List.of(),true));check(PestBaitTransfer.select(rules,1,LAYOUT,menu(protectedInv,AIR),protectedInv,traps(true)).isEmpty(),"protection vetoes exact ID");
  check(PestBaitTransfer.select(rules,1,LAYOUT,menu(inv,AIR),inv,PestTrapObservation.unknown()).isEmpty(),"unknown no-bait field not empty/authority");
  check(PestBaitTransfer.select(rules,1,new PestBaitTransfer.Layout("Pest Trap #1",27,13,8),menu(inv,AIR),inv,traps(true)).isEmpty(),"requested two cannot cap an eight-item left-click: actual declared capacity is mandatory");
  var hotbar=new HashMap<>(inv);hotbar.put(0,hotbar.remove(10));hotbar.put(10,AIR);check(PestBaitTransfer.select(rules,1,LAYOUT,menu(hotbar,AIR),hotbar,traps(true)).isEmpty(),"hotbar never supplies bait");
  check(PestBaitTransfer.select(new PestBaitTransfer.Rules("PLANT_MATTER",2,4,Set.of()),1,LAYOUT,menu(inv,AIR),inv,traps(true)).isEmpty(),"no pickup of a stack larger than authorized");
  F f=new F(2);var immutable=f.plan.baseline();try{immutable.put(42,item("OTHER",1));throw new AssertionError("mutable baseline");}catch(UnsupportedOperationException expected){}f.arm();f.pickup(false);check(f.proof.state()==PestBaitTransfer.State.AWAITING,"predicted pickup is not carried ownership");f.items.observe(1,7,28,AIR);f.cursors.observe(1,7,f.cursor,f.now+1);f.poll(true);check(f.proof.step()==PestBaitTransfer.Step.DEPOSIT&&f.proof.state()==PestBaitTransfer.State.READY,"both source and cursor server receipts before deposit");f.arm();f.deposit(true);check(f.proof.step()==PestBaitTransfer.Step.RETURN&&f.proof.state()==PestBaitTransfer.State.READY,"only owned exact six-item remainder may return to original empty slot");f.arm();f.returned(true);check(f.proof.state()==PestBaitTransfer.State.CONFIRMED&&f.actions==3&&f.inv.get(10).count()==6,"partial deposit plus owned return and trap update, no remaining cursor");
  f=new F(8);f.arm();f.pickup(true);f.arm();f.deposit(true);check(f.proof.state()==PestBaitTransfer.State.CONFIRMED&&f.actions==2,"whole-stack deposit needs no cursor repair");
  f=new F(2);f.arm();f.pickup(true);f.arm();f.deposit(false);check(f.proof.state()==PestBaitTransfer.State.AWAITING,"predicted bait/NoBait change not enough");f.cursors.observe(1,7,f.cursor,f.now+1);f.poll(false);check(f.proof.state()==PestBaitTransfer.State.AWAITING,"cursor alone is not target deposit proof");f.items.observe(1,7,13,f.bait);f.poll(false);check(f.proof.step()==PestBaitTransfer.Step.RETURN,"actual target update plus cursor before return");f.inv.put(10,item("OTHER",1));check(!f.proof.armNext(menu(f.inv,f.bait),f.inv,f.cursor,f.now)&&f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"manual occupied return slot cannot be overwritten");
  f=new F(8);f.arm();f.pickup(true);f.arm();f.bait=count(f.plan.item(),8);f.cursor=AIR;f.items.observe(1,7,13,f.bait);f.cursors.observe(1,7,AIR,f.now+1);f.poll(true);check(f.proof.state()==PestBaitTransfer.State.WAIT_TRAP,"inventory removal alone cannot claim baited trap");f.poll(false);check(f.proof.state()==PestBaitTransfer.State.CONFIRMED,"fresh exact trap leaves NoBait after physical empty cursor");
  f=new F(2);f.arm();f.pickup(true);f.arm();f.deposit(true);f.arm();f.returned(false);check(f.proof.state()==PestBaitTransfer.State.AWAITING,"predicted cursor return is not a recovered item");f.now+=9*S;f.poll(false);check(f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"no acknowledgement stops; never retry/repair/close");
  f=new F(2);check(f.proof.armNext(menu(f.inv,f.bait),f.inv,f.cursor,0),"fixture arm");check(!f.proof.sent(GuardedMenuAction.Result.UNCERTAIN,0)&&f.proof.state()==PestBaitTransfer.State.UNCERTAIN&&!f.proof.armNext(menu(f.inv,f.bait),f.inv,f.cursor,S),"uncertain native outcome is terminal and cannot replay");
  f=new F(2);f.arm();f.pickup(true);f.owned.set(false);f.poll(true);check(f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"revoked root loses all carried-item permission");
  f=new F(2);f.arm();f.pickup(true);f.inv.put(42,item("OTHER",1));f.poll(true);check(f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"equipment mutation invalidates complete baseline");
  f=new F(2);f.arm();f.pickup(true);f.proof.poll(2,menu(f.inv,f.bait),f.inv,f.cursor,new PestBaitTransfer.TrapFrame(2,f.now,traps(true)),false,f.now);check(f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"world changes cannot reuse cursor receipts");
  f=new F(2);f.arm();f.pickup(true);f.cursors.clear();check(!f.proof.armNext(menu(f.inv,f.bait),f.inv,f.cursor,f.now)&&f.proof.state()==PestBaitTransfer.State.UNCERTAIN,"lost server cursor scope revokes previously proved ownership before deposit");
  f=new F(2);f.arm();f.pickup(true);f.arm();f.deposit(true);f.cursors.observe(1,7,item("OTHER",6),f.now+1);f.now+=S/10;check(!f.proof.armNext(menu(f.inv,f.bait),f.inv,f.cursor,f.now),"changed server cursor cannot reuse physical old remainder as return authority");
  System.out.println("PestBaitTransferTest: PASS (explicit protected43 plan, exact owned pickup/deposit/remainder-return plus server cursor/slot/NoBait proofs, uncertainty/manual/world/deadline denial; declared direct-item layout only, no live GUI/action claim)");
 }
}
